import React from 'react';

const Icon = ({ path, extra }) => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    <path d={path} />
    {extra}
  </svg>
);

const NAV_ITEMS = [
  { id: 'students', label: 'Студенты', path: '/admin/students', icon: <Icon path="M5 20c1.5-3.5 4-5 7-5s5.5 1.5 7 5" extra={<circle cx="12" cy="8" r="3.5" />} /> },
  { id: 'groups', label: 'Группы', path: '/admin/groups', icon: <Icon path="M12 6c-2-1.5-4.5-2-8-2v14c3.5 0 6 .5 8 2 2-1.5 4.5-2 8-2V4c-3.5 0-6 .5-8 2Z M12 6v14" /> },
  { id: 'categories', label: 'Категории питания', path: '/admin/categories', icon: <Icon path="M3 5h18v16H3Z M8 3v4 M16 3v4 M3 10h18" /> },
  { id: 'reports', label: 'Отчеты', path: '/admin/reports', icon: <Icon path="M5 20v-10 M12 20V4 M19 20v-7" /> },
  { id: 'staff', label: 'Сотрудники', path: '/admin/staff', icon: <Icon path="M12 20s-7-4.5-9-9c-1.2-2.8.6-6 3.8-6 2 0 3.6 1.2 5.2 3 1.6-1.8 3.2-3 5.2-3 3.2 0 5 3.2 3.8 6-2 4.5-9 9-9 9Z" /> },
];

const AdminSidebar = ({ active }) => {
  return (
    <aside className="sticky top-0 hidden h-screen w-64 shrink-0 flex-col px-4 py-6 md:flex laptop:px-6">
      {/* Логотип */}
      <div className="flex items-center gap-3 px-2">
        <svg width="32" height="32" viewBox="0 0 24 24" fill="#0D0C0C" aria-hidden>
          <path d="M2 4 L22 12 L2 20 L8 12 Z" />
        </svg>
        <span className="text-xl font-semibold text-black">Талон</span>
      </div>

      {/* Навигация */}
      <p className="mt-8 px-3 text-xs leading-[120%] text-gray">Навигация</p>
      <nav className="mt-2 flex flex-col gap-1">
        {NAV_ITEMS.map((item) => (
          <button
            key={item.id}
            type="button"
            onClick={() => {
              // TODO: переход на страницу раздела, когда она будет свёрстана
              if (item.path === '/admin/students') window.location.assign('/admin/students');
            }}
            className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm transition-colors
              ${active === item.id ? 'bg-accent font-medium text-black' : 'text-gray hover:text-black'}`}
          >
            {item.icon}
            {item.label}
          </button>
        ))}
      </nav>

      {/* Профиль */}
      <p className="mt-8 px-3 text-xs leading-[120%] text-gray">ПРОФИЛЬ</p>
      <div className="mt-2 flex flex-col gap-1">
        <div className="rounded-lg bg-gray/10 px-3 py-2.5">
          <p className="text-sm font-medium text-gray">Администратор</p>
          <p className="mt-0.5 text-xs text-gray">moderator@univ.ru</p>
        </div>
        <button type="button" className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-gray hover:text-black" onClick={() => { /* TODO: уведомления */ }}>
          <Icon path="M6 9a6 6 0 1 1 12 0c0 5 2 6 2 6H4s2-1 2-6 M10 19a2 2 0 0 0 4 0" />
          Уведомления
          <span className="ml-auto h-2 w-2 rounded-full bg-[#F24444]" aria-hidden />
        </button>
        <button type="button" className="flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-gray hover:text-black" onClick={() => { /* TODO: настройки */ }}>
          <Icon path="M12 2v3 M12 19v3 M2 12h3 M19 12h3 M4.9 4.9l2.1 2.1 M17 17l2.1 2.1 M19.1 4.9L17 7 M7 17l-2.1 2.1" extra={<circle cx="12" cy="12" r="3" />} />
          Настройки
        </button>
      </div>
    </aside>
  );
};

export default AdminSidebar;
